<script setup lang="ts">import {ShoppingBag,X,Minus,Plus,Trash2} from 'lucide-vue-next';import {useCart,useSession,useUi} from '../stores';import {idr} from '../api';import {useRouter} from 'vue-router';const cart=useCart(),session=useSession(),ui=useUi(),router=useRouter();async function update(id:string,value:number){try{if(value<1)await cart.remove(id);else await cart.quantity(id,value)}catch(e:any){ui.toast(e.message,'error')}}function checkout(){ui.cartOpen=false;router.push(session.user?'/checkout':'/login')}</script>
<template><Teleport to="body"><Transition name="drawer"><div v-if="ui.cartOpen" class="drawer-shell" role="dialog" aria-modal="true" aria-label="Shopping bag"><button class="drawer-backdrop" aria-label="Close bag" @click="ui.cartOpen=false"></button><aside class="cart-drawer"><header><div><ShoppingBag :size="19"/><h2>Your Shopping Bag</h2></div><button class="icon-button" @click="ui.cartOpen=false"><X :size="20"/></button></header><div v-if="!cart.cart?.items.length" class="drawer-empty"><ShoppingBag :size="50"/><h3>Your bag is currently empty</h3><p>Explore our catalog to find items you love.</p><button class="btn-primary" @click="ui.cartOpen=false;router.push('/products')">Start Shopping</button></div><div v-else class="drawer-items"><article v-for="item in cart.cart.items" :key="item.id"><img :src="item.product.images[0]?.imageUrl" :alt="item.product.name"/><div><small>{{item.product.category.name}}</small><h3>{{item.product.name}}</h3><b>{{idr(item.product.price)}}</b><div class="drawer-stepper"><button @click="update(item.id,item.quantity-1)"><Minus :size="12"/></button><span>{{item.quantity}}</span><button @click="update(item.id,item.quantity+1)"><Plus :size="12"/></button><button class="trash" @click="cart.remove(item.id)"><Trash2 :size="14"/></button></div></div></article></div><footer v-if="cart.cart?.items.length"><div><span>Subtotal</span><b>{{idr(cart.total)}}</b></div><p>Taxes and shipping calculated at checkout.</p><button class="btn-primary wide" @click="checkout">Proceed to Checkout</button></footer></aside></div></Transition></Teleport></template>
